#pragma once

#include <algorithm>

#include "espdet_detect.hpp"  // Generated by Espressif ESP-Detection's ESP-DL template.
#include "../temporal_gate.hpp"

// Thin ESP-IDF adapter: pass a decoded RGB frame from the OV5640 camera.
// ESPDetDetect handles model preprocessing, inference, and box decoding.
class DeerPresenceSignal {
 public:
  template <typename Image>
  bool update_frame(Image& rgb_frame) {
    const auto& detections = detector_.run(rgb_frame);
    float deer_confidence = 0.0f;
    for (const auto& detection : detections) {
      if (detection.category == 0) {
        deer_confidence = std::max(deer_confidence, detection.score);
      }
    }
    return gate_.update(true, deer_confidence);
  }

  // Call after camera or inference failure to discard stale detections.
  bool invalidate_frame() { return gate_.update(false, 0.0f); }
  void reset() { gate_.reset(); }

 private:
  ESPDetDetect detector_;
  TemporalDeerGate gate_;
};
